/* ===========================================================================
 * meanings-i18n.js — 語釈の訳（英語・中国語・ベトナム語・韓国語）
 *
 * 3,660語すべては入っていない。訳のある語だけ差し替え、無い語は日本語の
 * 語釈をそのまま出す（外国語で遊ぶときは、そこに辞書を引く導線を添える）。
 * まず ROUND 01「〇ん〇ん」64語を入れてある。増やし方は meanings-i18n.md。
 *
 * 鍵は答えのかな（data.js の word）。日本語の語釈と同じ順・同じ区切り（/）で
 * 書くと、日本語と見くらべたときに読みが合う。区切りの前後は、英語・
 * ベトナム語・韓国語は空け、中国語だけ空けない。
 *
 * 同じかなが別のラウンドに別の語釈で入っていることがある（〇ん〇ん の
 * 「しんしん＝雪が静かに降る」と 〇んしん の「しんしん＝心身」）。その語だけ
 * 「テンプレート＋タブ＋かな」を鍵にする。game.js の meaningOf() が
 * そちらを先に見て、無ければ かなだけの鍵に落ちる。
 *
 * 語数が増えて 300KB を超えたら、言語ごとのファイルに割ること。
 * =========================================================================== */
