"がんせい": "眼睛的機能。「眼精疲労」（眼疲勞）。",
"ねんせい": "黏稠、黏糊的性質；黏性。",
"ひんせい": "為人的品格。「品性を疑う」（懷疑其人品）。",
"らんせい": "卵生，由卵孵化而生。「卵生動物」/秩序大亂的時世。",
"りんせい": "輪生，葉子在莖的同一高度環狀著生。",
"ざんせい": "剩下的人生；餘生。",
"べんせい": "鞭打馬匹的聲音。出自賴山陽的詩句「鞭声粛々（べんせいしゅくしゅく）夜河を渡る」。",
