"むずむず": "發癢似的刺激感。/想做什麼而坐立不安的樣子。",
"ぐずぐず": "決斷或行動遲緩、拖拖拉拉的樣子。/不停地發牢騷的樣子。",
"おずおず": "因害怕或沒自信而畏畏縮縮、猶豫著行動的樣子。",
"しずしず": "安靜、緩慢而從容地行動的樣子。",
"かずかず": "許多東西。各種各樣。",
"くずくず": "容易碎裂崩塌的樣子。/嘟嘟囔囔、拖拖拉拉的樣子。",
"まずまず": "雖不充分，但還算令人滿意的樣子。",
"みずみず": "以「みずみずしい」的形式，表示新鮮有光澤的樣子。",
"ひんやり": "感覺涼颼颼的樣子。",
"ぼんやり": "模糊不清的樣子。/心不在焉、注意力渙散的樣子。",
"ずんぐり": "個子矮、身形粗圓的樣子。",
"どんぐり": "橡實，殼斗科（山毛櫸科）樹木結的硬殼果實。",
"あんぐり": "驚得目瞪口呆、大張著嘴的樣子。",
"でんぐり": "翻倒、翻轉。見於「でんぐり返し」（前滾翻）「でんぐり返る」。",
"かんぐり": "把別人的言行往壞處猜測。「勘ぐる」的名詞形。",
"ざんぐり": "寬鬆粗疏地編織或穿著的樣子。",
"うっとり": "被美等吸引住、陶醉忘我的樣子。",
"おっとり": "性格從容寬厚、不斤斤計較的樣子。",
"しっとり": "濕潤適度的樣子。/沉靜而有情致的樣子。",
"じっとり": "因汗水等而黏濕難受的樣子。",
"ねっとり": "黏性很強的樣子。",
"べっとり": "黏稠的東西厚厚地沾附著的樣子。",
"むっとり": "熱氣或濕氣悶在裡面、令人喘不過氣的樣子。",
"はっとり": "日本常見的姓氏「服部」。以伊賀忍者服部半藏而聞名。",
"のっとり": "用武力強行奪取。即「劫持、強佔」。",
"とっとり": "日本中國地方的縣「鳥取」。以鳥取沙丘聞名。",
"てっとり": "以「手っ取り早い」的形式，表示省事、快捷。",
"ぺっとり": "平貼著黏附上去的樣子。",
"ぎっとり": "油脂等厚重黏膩的樣子。",
"ぴっとり": "緊緊靠攏、密合貼合的樣子。",
"ふしぶし": "身體的各個關節。/事情的種種之處、各個點。",
"はしばし": "事物各處的邊角與片段。話語、態度中的細微之處。",
"としどし": "每年。逐年。",
"ほしぼし": "天空中閃爍的眾多星星。",
"つくづく": "深深感觸於心的樣子。/仔細地、好好地。",
"ふくぶく": "以「福々しい」的形式，表示圓潤豐滿、一臉有福氣的樣子。",
"しみじみ": "打心底深深感受的樣子。/敞開心扉、靜靜相對的樣子。",
"かみがみ": "眾多的神。日本所說的「八百万」諸神。",
"すみずみ": "每一個角落。直到細枝末節。",
"ひさびさ": "距上次已隔了很久。",
"くさぐさ": "各種各樣的種類。形形色色。",
"ひろびろ": "顯得十分寬闊舒展的樣子。",
"くろぐろ": "顯得又黑又濃的樣子。",
"かろがろ": "「軽々しい」（輕率）的舊說法。",
"はろばろ": "「はるばる」的舊說法。從遙遠之處。",
"たえだえ": "眼看就要中斷卻仍勉強延續的樣子。「息も絶え絶え」（氣息奄奄）。",
"さえざえ": "澄澈透明、清晰分明的樣子。",
"ひえびえ": "顯得十分寒冷的樣子。",
"こえごえ": "眾人的聲音。「声々に叫ぶ」（眾口齊呼）。",
"すえずえ": "將來。前途。「末々まで」（直到將來）。",
"きえぎえ": "眼看就要消失的樣子。「消え消えになる」。",
"たんどく": "單獨一人或單獨一個進行。",
"おんどく": "出聲朗讀。/按漢字的音讀來讀。",
"はんどく": "推測辨認難以辨讀的文字。",
"らんどく": "隨手抓到什麼就讀什麼地讀書。",
"りんどく": "幾個人輪流朗讀並相互解釋研討。",
"くんどく": "按日語語序閱讀漢文。",
"なんどく": "讀法很難。「難読漢字」是難讀的漢字。",
"つんどく": "買了書卻不讀，堆在一旁。",
"さんどく": "佛教中損害心性的三種煩惱（貪、瞋、癡）。",
"かんどく": "書信、信函。",
"せかい": "地球上的一切。人類生活的整個場所。",
"せまい": "面積或寬度小。「心が狭い」（心胸狹窄）。",
"せだい": "生活於同一時代的年齡層，世代。「世代交代」（世代更替）。",
"せたい": "共同居住並共同維持生計的一群人，即家戶。",
"せんい": "細如絲線的東西，纖維。「食物繊維」（膳食纖維）。",
"せいい": "沒有謊言與欺瞞的真心，誠意。",
"せこい": "小氣吝嗇。狡猾而格局小。原是藝人與廟會攤販的隱語。",
"せおい": "背在背上。「背負い投げ」（柔道的背負投）。",
"せきい": "天球上相當於緯度的座標，赤緯。",
"えらい": "了不起、值得敬佩。/在中部、關西等地也用來表示「累」「糟糕」之意。「えらい目にあった」（吃了大苦頭）。",
"えぐい": "澀味重、刺喉的味道。/在網路與年輕人用語中也用作「厲害」「糟糕」的強調。",
"えたい": "真面目、本來面目。「得体の知れない人物」（來路不明的人物）。",
"えもい": "網路與年輕人用語，指心被強烈打動、難以言喻的感受。",
"えろい": "口語，指帶有性感、色情意味的樣子。",
"えずい": "西日本方言，意為「噁心」「過分、糟糕」。",
"ええい": "下決心或不耐煩時發出的聲音。",
"えいい": "全心投入、努力不懈的樣子。「鋭意努力する」（銳意努力）。",
"かんびょう": "照顧病人。",
"なんびょう": "難以治癒的疾病。",
"まんびょう": "各種各樣的疾病。「風邪は万病のもと」（感冒是百病之源）。",
"さんびょう": "三個秒，三秒。",
"てんびょう": "天平，奈良時代的年號（729〜749）。「天平文化」。",
"りんびょう": "性傳播疾病之一，淋病。",
"がんびょう": "眼睛的疾病。「眼病を患う」（患眼疾）。",
"すんびょう": "極其短暫的時間。「寸秒を争う」（分秒必爭）。",
"ふんびょう": "分與秒。極短的時間。「分秒を争う」（分秒必爭）。",
"せんびょう": "只用線條描繪，線描、白描。",
"ぐんびょう": "軍隊、作戰部隊。",
"かんとく": "監督指導的人。「映画監督」指電影導演。",
"じんとく": "一個人自身具備的德行。「人徳がある」（有德望）。",
"あんとく": "傳說與平家一同沉入海中的幼帝。「安徳天皇」（安德天皇）。",
"もんとく": "平安前期的天皇。「文徳天皇」（文德天皇）。",
"そんとく": "損失與利益。「損得勘定」（算計得失）。",
"いんとく": "藏匿起來不讓別人知道。",
"にんとく": "仁德天皇。以世界最大級別的古墳聞名。",
"おんとく": "恩惠，以及仁厚寬和的品性。",
"さんとく": "三種德。「三徳包丁」指多用途的三德菜刀。",
"しんとく": "神所具有的恩惠與力量。",
"てんとく": "上天賜予的德。也是平安中期的年號。",
"けんとく": "建德，南北朝時代南朝的年號。",
"ぜんとく": "好的德行、美德。",
"みんとく": "民眾、國民的道德。",
"せんとく": "「不做算了、先別做」的隨便說法。",
"ちんみ": "難得嘗到的美味。",
"かんみ": "甜味。「甘味処」是賣日式甜點的店。",
"さんみ": "酸味。/三個位次。「三位一体」。",
"しんみ": "像親人一樣真心關懷的樣子。",
"ぎんみ": "仔細查驗挑選。「素材を吟味する」（嚴選食材）。",
"がんみ": "細細品味。「熟読玩味」（熟讀玩味）。",
"えんみ": "鹽的味道，鹹味。也讀作「えんあじ」。",
