"たんみ": "清淡的味道。",
"りかい": "領會意思或情況。",
"りせい": "有條理地思考的能力，理性。",
"りけい": "自然科學類的學科領域，理科。",
"りさい": "遭受災害。「罹災証明」是受災證明。",
