"こっそり": "偷偷地、不讓人察覺的樣子。",
"げっそり": "突然消瘦，或一下子沒了精神的樣子。",
"ごっそり": "一次幾乎全部消失或被拿走的樣子。",
"ひっそり": "靜悄悄沒有人影、不引人注意的樣子。",
"ほっそり": "身形纖細修長的樣子。",
