"さびさび": "冷清寂寥、靜悄悄的樣子。",
"わざわざ": "特意花工夫只為這件事。",
"ぎざぎざ": "像鋸齒一樣細細刻出缺口的樣子。",
"まざまざ": "歷歷在目，彷彿就在眼前。",
"むざむざ": "毫不可惜地、束手無策地。如「むざむざ渡すものか」。",
"がざがざ": "「がさがさ」的加強說法。",
"すんなり": "纖細柔韌的樣子。/事情順利無阻地進行。",
