"たぶたぶ": "液體滿滿當當地晃動的樣子。",
"どぶどぶ": "咕咚咕咚猛倒液體的聲音與樣子。",
"ずぶずぶ": "深深陷進去的樣子。/關係深度勾結的樣子。",
"つぶつぶ": "小顆粒聚在一起的樣子。",
"らぶらぶ": "口語，指情侶甜甜蜜蜜、感情很好的樣子。",
"でぶでぶ": "胖得厲害的樣子。",
"ごぶごぶ": "優劣或可能性不相上下，五五波。",
"ばぶばぶ": "模仿嬰兒聲音的詞。網路上也用。",
"こぶこぶ": "長出好幾個瘤塊的樣子。",
"ぐぶぐぶ": "漱口時咕嚕咕嚕的聲音。",
"ときどき": "偶爾，時不時。",
"さきざき": "將來，今後。/所到的各處。",
