"しなじな": "各式各樣的物品。",
"げんばく": "原子彈。利用核分裂的炸彈。",
"きんばく": "緊緊地捆綁起來。",
"はんばく": "反駁對方的意見。也讀作「はんぱく」。",
"えんばく": "燕麥。燕麥片的原料。",
"ろんばく": "論證攻擊對方的主張。",
"べんばく": "對對方的主張提出反駁。",
"ぎんばく": "把銀捶成紙一樣薄的銀箔。",
"みらい": "今後，未來。",
"みまい": "探望病人等以示慰問。",
