"みかい": "尚未開發的狀態。如「未開の地」（未開之地）。",
"みすい": "做到一半沒有得逞，未遂。",
"みめい": "天還沒有完全亮的時候，凌晨。",
"みんい": "國民的意願，民意。",
"みつい": "三井，日本代表性的財閥與企業集團名稱。",
"みたい": "表示「〜のようだ」（好像……）的隨意說法。",
"みせい": "還沒有完成。如「未成年」（未成年）。",
"みだい": "將軍或大臣的正妻。如「御台所」。",
"みさい": "未完成、未付款、未結清的狀態。",
"みよい": "外觀好看。/容易看清。",
"みれい": "禮拜三次。",
"わらい": "笑，笑聲。如「笑いを誘う」（引人發笑）。",
"わるい": "不好，不可取。",
"わかい": "年紀輕。/停止爭執、和好。",
"わだい": "談論的題材，話題。如「話題の人」（話題人物）。",
"わへい": "停止戰爭、走向和平。",
"わせい": "日本製造。如「和製英語」（日本自造的英語詞）。/和弦的連接，和聲。",
"わえい": "日語和英語。如「和英辞典」（日英詞典）。",
"わさい": "和服的裁縫。",
"わめい": "在日本的叫法、名稱。",
"わあい": "高興時發出的歡呼聲。",
"わりい": "「悪い」的隨意說法。如「わりい、遅れた」（抱歉，我遲到了）。",
"わたい": "「わたし」（我）的隨意而古舊的說法。",
"わろい": "「悪い」的古舊說法與方言形式。",
"すごい": "程度非常厲害。",
"すまい": "居住的房子，住處。",
"すくい": "拯救、幫助。如「救いの手」（援手）。",
"すいい": "隨時間推移而變化。",
"すぱい": "暗中刺探情報的人，間諜。",
"すかい": "天空。如「スカイツリー」（晴空塔）。",
"すうい": "反芻動物的第四胃，皺胃。",
"すげい": "了不得，好得令人難以置信。",
"すてい": "停留、逗留。如「ホームステイ」（寄宿家庭）。",
"すたい": "嬰兒的圍兜。",
"つよい": "有力量，不脆弱。",
"つらい": "痛苦，難以忍受。",
"つかい": "受託辦事而前往，或指跑腿的人。",
"つがい": "雌雄成對的一組。如「つがいの鳥」（一對鳥）。",
"つたい": "沿著某物前進。如「壁伝いに歩く」（沿著牆走）。",
"つどい": "人的聚會，集會。",
"つつい": "筒形的水井。也是姓氏與地名，如「筒井筒」「筒井順慶」。",
"つぼい": "源自地名的姓氏。各地都有，如地球物理學家坪井忠二。",
"つくい": "神奈川縣的地名。如「津久井湖」（津久井湖）。",
"たっぷり": "分量或時間十分充裕的樣子。",
"どっぷり": "深深浸泡的樣子。/深陷於某種狀態。",
"がっぷり": "相撲等中雙方緊緊扭抱在一起的樣子。如「がっぷり四つ」。",
"でっぷり": "身體肥胖、肚子明顯凸出的樣子。",
"とっぷり": "天完全黑下來的樣子。/浸泡得十分充分的樣子。",
"ずっぷり": "深深浸泡的樣子。同「どっぷり」。",
"やまやま": "很多山。/用「〜したいのはやまやま」的說法，表示很想那樣做。",
"たまたま": "偶然地。偶爾。",
"ちまちま": "小巧而收拾得整齊的樣子。",
"にまにま": "掩不住高興，獨自暗暗微笑的樣子。",
"さまさま": "用「〜さまさま」的說法，指值得感激的存在。如「お客さまさま」。",
"あまあま": "口語，指味道很甜，或評價、態度非常寬鬆。",
"うまうま": "巧妙地、輕易地上當，如「うまうまとだまされる」。/幼兒語，指好吃的東西。",
"しましま": "條紋一道道排列的樣子。",
"いまいま": "用「忌々しい」的形式，表示令人惱火的樣子。",
"だまだま": "粉末結成小疙瘩的樣子。",
"ひまひま": "一有空隙的時候。如「暇々に本を読む」。",
"がっしり": "骨架結實、強壯的樣子。",
"ぎっしり": "毫無縫隙地塞得滿滿的樣子。",
"ずっしり": "沉甸甸、拿在手上很有分量的樣子。",
"どっしり": "穩重、沉著的樣子。",
"びっしり": "滿滿一片、毫無空隙地排列的樣子。",
"のっしり": "龐大的身軀沉重地走動的樣子。",
"みっしり": "毫無縫隙地填滿的樣子。/充分地。如「みっしり仕込む」。",
"ぴっしり": "毫無縫隙地密集或緊貼的樣子。/把工作做得很充分的樣子。",
"にっこり": "不出聲、開心地微笑的樣子。",
"ほっこり": "溫暖、讓人心裡舒坦的樣子。/蒸得鬆軟飽滿的樣子。",
"ぽっこり": "只有一部分圓圓鼓起的樣子。",
"もっこり": "隆起成小丘狀的樣子。",
"ぼっこり": "突然凹陷，或圓圓鼓起的樣子。",
"まっこり": "馬格利，用米釀的韓國濁酒。",
"まじまじ": "目不轉睛、直直盯著看的樣子。",
"もじもじ": "猶豫不安、身體扭來扭去的樣子。",
"うじうじ": "下不了決心、拖拖拉拉的樣子。",
"ぐじぐじ": "不把不滿說清楚，卻沒完沒了地嘀咕的樣子。",
"いじいじ": "卑屈拘泥、放不開的樣子。",
"たじたじ": "被對方氣勢壓倒而退縮的樣子。",
"げじげじ": "多足的蟲，蚰蜒。如「げじげじ眉」。",
"がじがじ": "反覆啃咬硬東西的樣子。",
"つじつじ": "各處的街頭巷口。",
"ねじねじ": "扭曲擰結的樣子。",
"ぷにぷに": "柔軟有彈性、一按就陷下去的樣子。",
"ぐにぐに": "柔軟而能隨意彎曲的樣子。",
"ふにふに": "軟綿綿、沒有力氣的樣子。",
"むにむに": "反覆按壓、揉捏柔軟東西的樣子。",
"なになに": "要對方再說一遍時用的詞。/代替省略內容的詞。",
"ひにひに": "一天比一天地、逐日。",
"まにまに": "聽憑事情自然發展的樣子。如「波のまにまに」。",
"うにうに": "柔軟的東西不成形地蠕動的樣子。",
"てにてに": "各自手裡拿著。如「手に手に旗を振る」。",
"ちりぢり": "原本聚在一起的東西四散分開的樣子。",
"とりどり": "各不相同的樣子。如「色とりどり」。",
"こりごり": "吃過苦頭，再也不想經歷第二次。",
"さまざま": "種類、形狀、樣子等各式各樣。",
"しまじま": "許多島嶼。各處的島。",
"くまぐま": "各處的角落。每個角落。",
"こまごま": "瑣碎細小的樣子。如「細々とした用事」。",
"それぞれ": "一個一個、一人一人。各自。",
"くれぐれ": "反覆叮嚀、誠心誠意地。通常用「くれぐれも」的形式。",
"つれづれ": "無事可做、無聊的樣子。/沉浸於思緒的樣子。",
"はればれ": "天空完全放晴的樣子。/心結解開、神清氣爽的樣子。",
"ほれぼれ": "被徹底吸引、看得入迷的樣子。",
"きれぎれ": "失去連貫、斷成一段一段的樣子。",
"かれがれ": "草木枯萎凋零的樣子。",
"はやばや": "比預定或預想的更早。早早地。",
"つやづや": "「つやつや」的連濁形式。有古例可考的罕見形式。",
"ひとびと": "許多人。大家。",
"ふとぶと": "又粗又壯、氣派十足的樣子。",
"ことごと": "一切事情。也用「ことごとく」「事々しい」的形式。",
"さとざと": "各處的村落。",
"しらじら": "天亮泛白的樣子。/一眼看穿、令人掃興的樣子。",
"からがら": "好不容易才。如「命からがら逃げ出す」。",
