"どんたく": "休息日。/福岡的祭典「博多どんたく」。源自荷蘭語 zondag。",
"でんたく": "電子式桌上型計算器。",
"そんたく": "揣度對方的心思。",
"しんたく": "出於信任把財產託付給他人。/神的旨意、神諭。",
"ゆんたく": "沖繩方言，指閒聊。",
"おんたく": "恩惠、福澤。如「恩沢に浴する」。",
