"だんな": "丈夫。/商家的主人、老闆。",
"かんな": "刨刀，削平木材表面的工具。/美人蕉，夏天開紅色或黃色的花。",
"へんな": "與平常不同、奇怪的樣子。如「変な人」。",
"にんな": "仁和，平安時代的年號。如「仁和寺」。",
