"ぶんな": "北朝的年號「文和」（1352～1356年）。",
"をんな": "「おんな」的歷史假名寫法。",
"おもい": "有分量、沉重。/心中懷有的想法。",
"おおい": "數量很多。/蓋在上面的東西、罩子。",
"おそい": "速度慢。/時間晚。",
"おしい": "捨不得放手。可惜。",
"おれい": "感謝的心意，或表示謝意的禮品。",
"おめい": "壞名聲。如「汚名返上」。",
"おすい": "髒水，如生活污水。",
"おうい": "王位、國王的地位。也是將棋頭銜之一。",
"おだい": "費用、價錢。如「お代はけっこう」。",
"おでい": "骯髒的泥、污泥。如「下水汚泥」。",
