"おまい": "「おまえ」的隨便說法。",
"おさい": "配飯吃的菜。",
"おんい": "恩惠與威嚴。如「恩威並び行う」。",
"おくい": "藏在心底的真正意圖。",
"ながい": "距離或時間很大、很長。",
"ならい": "世間的習俗。/以某物為範本、效仿。",
"なんい": "難與易。如「難易度」。",
"なかい": "在旅館或料亭照料客人的女性。",
"なさい": "表示委婉命令的詞，如「しなさい」。",
"なだい": "有名、著名。如「名代の品」。",
"なつい": "年輕人用語，「懐かしい」的縮略說法。",
"なるい": "坡度平緩。也指做法寬鬆、不夠嚴厲。",
"ないい": "不擺到明面上的意向。如「内意を伝える」。",
"なうい": "時髦、有當下感的樣子。1980年代的流行語。",
"てはい": "分派任務、做好安排。/通緝。",
"てんい": "移到別的地方。/上天的心意。",
"てあい": "那類傢伙。/圍棋、將棋的對局。",
"てぬい": "不用機器，用手縫製。",
"てらい": "賣弄知識或才能。如「衒いがない」。",
"てきい": "把對方視為敵人的心情、敵意。",
"ておい": "身上帶傷。如「手負いの獣」。",
"てせい": "親手做的。手工製作。",
"てだい": "商家中地位介於「番頭」和「丁稚」之間的夥計。",
"てぜい": "自己直接掌握的兵力。",
"ていい": "確定位置。如「定位置」「定位脳手術」。",
"てがい": "親自飼養動物。",
"まよう": "迷路，或心裡拿不定主意。",
"まほう": "以不可思議的力量引發異常之事的法術，魔法。",
