"せんせん": "Run sợ, nơm nớp. Chính là sen-sen trong 戦々恐々.",
"ぜんぜん": "Hoàn toàn (đi với phủ định); trong khẩu ngữ còn dùng để nhấn mạnh khẳng định.",
"たんたん": "Điềm nhiên, không lộ cảm xúc.",
"だんだん": "Dần dần. / Xếp thành bậc thang.",
"ちんちん": "Nóng bỏng (khẩu ngữ, tuỳ vùng). / Tiếng kim loại lanh canh.",
