"でんでん": "Dạng tiếng trẻ con thấy trong dendenmushi (con ốc sên).",
"とんとん": "Tiếng gõ nhẹ. / Mọi việc trôi chảy.",
"どんどん": "Dồn dập tiến tới. / Tiếng trống.",
"なんなん": "Cách nói khẩu ngữ nhấn mạnh của 'cái gì thế'.",
"にんにん": "Tiếng hô đùa gắn với ninja.",
"ねんねん": "Năm này qua năm khác.",
"はんはん": "Chia đôi, mỗi bên một nửa.",
"ばんばん": "Làm liên tục và mạnh mẽ. / Tiếng đập mạnh.",
"ぱんぱん": "Căng phồng hết cỡ. / Tiếng vỗ tay liên tiếp.",
"ひんひん": "Tiếng ngựa hí cao.",
"びんびん": "Kích thích, âm thanh hay đà truyền tới rất mạnh.",
"ぴんぴん": "Khoẻ mạnh, sống động. / Căng thẳng ra.",
"ふんふん": "Tiếng ngân nga hay thở bằng mũi. / Tiếng ừ hử nhẹ.",
"ぶんぶん": "Tiếng vo ve của côn trùng. / Tiếng vung mạnh vật gì đó.",
"ぷんぷん": "Mặt nặng mày nhẹ vì giận. / Mùi bốc lên nồng nặc.",
