"ごきごき": "Tiếng khớp xương hay vật cứng kêu đục.",
"なきなき": "Vừa khóc vừa làm. Đành chịu, không còn cách nào.",
"てきてき": "Từng giọt rơi nối tiếp nhau.",
"せきせき": "Tĩnh lặng và quạnh quẽ.",
"よきよき": "Lặp lại yoki (= tốt); tiếng lóng trên mạng và của giới trẻ, tỏ ý hài lòng, tán thành.",
