"わきわき": "Bàn tay liên tục nắm vào xoè ra.",
"ふきふき": "Lau đi lau lại nhiều lần, như trong 'vừa lau miệng vừa nói'.",
"えきえき": "Sáng rực rỡ. Khí thế mạnh mẽ.",
"ぐきぐき": "Đau nhức từng cơn. / Cử động cứng nhắc, vụng về.",
"へきへき": "Phát ngán, không chịu nổi nữa.",
"べきべき": "Mây hay bụi cuồn cuộn dâng lên phủ kín.",
"びきびき": "Tiếng nứt vỡ đánh rắc. / Giận đến mức mạch máu như sắp đứt.",
