"はんがく": "Nửa giá.",
"らんがく": "Ngành học thời Edo, tìm hiểu phương Tây qua tiếng Hà Lan.",
"でんがく": "Món ăn nướng phết tương miso. / Nghệ thuật biểu diễn thờ thần ruộng đồng.",
"ざんがく": "Số tiền còn lại.",
"ぐんがく": "Âm nhạc của quân đội. 「軍楽隊」 (đội quân nhạc).",
"ほんがく": "Ngành học vốn có. Cũng có nghĩa là trường đại học này.",
"べんがく": "Chăm chỉ dùi mài học vấn.",
"りんがく": "Ngành học nghiên cứu việc trồng và sử dụng rừng; lâm học.",
"ばんがく": "Bắt đầu học hành khi đã có tuổi.",
"まんがく": "Đủ đúng số tiền đã yêu cầu. 「満額回答」 (đáp ứng trọn vẹn yêu cầu).",
"げんいん": "Cái làm nảy sinh sự việc; nguyên nhân.",
"ぜんいん": "Tất cả mọi người có mặt.",
