"まんいん": "Đã kín chỗ, đủ số người quy định.",
"せんいん": "Người làm việc trên tàu; thuỷ thủ.",
"こんいん": "Việc kết hôn. 「婚姻届」 (tờ đăng ký kết hôn).",
"けんいん": "Việc kéo đi. 「牽引車」 (xe kéo).",
"じんいん": "Số người, nhân sự. 「人員整理」 (cắt giảm nhân sự).",
"さんいん": "Phía biển Nhật Bản của vùng Chugoku. 「山陰地方」 (vùng San'in).",
"きんいん": "Con dấu bằng vàng. Chiếc ấn vàng khắc 「漢委奴国王」.",
"だんいん": "Người thuộc một đoàn thể; đoàn viên.",
"えんいん": "Nguyên nhân xa. Ngược với 「近因」 (nguyên nhân gần).",
"かんいん": "Quan hệ nam nữ trái luân thường; gian dâm.",
"しんいん": "Nguyên nhân nằm ở tâm lý. 「心因性」 (do tâm lý).",
"ぶんいん": "Bệnh viện hay chùa chi nhánh, tách ra từ cơ sở chính.",
