"らんいん": "Đông Ấn Hà Lan.",
"ぴんいん": "Cách ghi phát âm tiếng Trung bằng chữ Latinh. Pinyin.",
"にんいん": "Con dấu dùng hằng ngày, không phải dấu đã đăng ký chính thức.",
