"はんえん": "Hình nửa vòng tròn; bán nguyệt.",
"げんえん": "Giảm lượng muối.",
"でんえん": "Ruộng đồng và đồng nội. Vùng quê. 「田園風景」 (phong cảnh đồng quê).",
"せんえん": "Một nghìn yên. 「千円札」 (tờ một nghìn yên).",
"しんえん": "Vực nước sâu. / Chiều sâu khôn dò.",
"けんえん": "Ví von cho quan hệ xấu, không hợp nhau. 「犬猿の仲」 (như chó với mèo).",
"ふんえん": "Khói do núi lửa phun lên.",
"がんえん": "Muối khai thác từ trong lòng đất; muối mỏ.",
"ぶんえん": "Tách riêng khu vực được hút thuốc.",
"うんえん": "Mây và sương mù. 「雲煙過眼」 (coi mọi sự nhẹ như mây khói lướt qua mắt).",
"くんえん": "Xông bằng khói. 「燻煙剤」 (thuốc xông khói).",
"じんえん": "Khói bếp từ nhà dân. Dấu hiệu có người sinh sống. 「人煙まれ」 (thưa vắng bóng người).",
"らんえん": "Hình bầu dục như quả trứng. 「卵円孔」 (lỗ bầu dục).",
"さんえん": "Ba con khỉ: không nhìn, không nghe, không nói điều xấu.",
"ぜんえん": "Mép phía trước. 「翼の前縁」 (mép trước của cánh).",
"ぎんえん": "Hợp chất của bạc. Vật liệu cảm quang trong ảnh phim. 「銀塩カメラ」 (máy ảnh phim).",
"ざんえん": "Cái nóng còn sót lại khi đã sang thu.",
"てんえん": "Kéo dài ra và dàn rộng. 「展延性」 (tính dẻo, dát mỏng được).",
