"ろんり": "Cách dựng nên mạch lý lẽ; logic.",
"りんり": "Đạo lý con người phải giữ; luân lý, đạo đức.",
"ぶんり": "Tách ra và rời khỏi nhau.",
"きんり": "Lãi tính trên khoản tiền cho vay hay đi vay.",
"せんり": "Quãng đường rất xa. 「千里の道も一歩から」 (đường ngàn dặm bắt đầu từ một bước chân).",
