"えんり": "Chán ngán cõi đời này mà lìa bỏ nó.",
"らんり": "Người ta ly tán khắp nơi vì chiến loạn.",
"はんり": "Nửa ri; khoảng hai ki-lô-mét.",
"きんむ": "Làm việc tại nơi công tác.",
"にんむ": "Bổn phận phải hoàn thành; nhiệm vụ.",
