"しんたん": "Gan dạ, lá gan. Như 「心胆を寒からしめる」 (làm người ta lạnh gáy). / Củi và than.",
"じんたん": "Viên bạc nhỏ ngậm cho thơm miệng, mát họng. Sản phẩm của hãng Morishita Jintan.",
"けんたん": "Ăn khoẻ, không kén chọn. Như 「健啖家」 (người ăn khoẻ).",
"てんたん": "Không tham lam, đạm bạc thanh thản. Như 「無欲恬淡」.",
"○んたん\tたんたん": "Điềm nhiên, không lộ cảm xúc. / Bằng phẳng trải dài.",
"げんたん": "Giảm diện tích gieo trồng, nhất là diện tích trồng lúa.",
"なんたん": "Mũi cực nam.",
"ぼんたん": "Quả bưởi, tên gọi khác của buntan. Cũng thấy trong tên kẹo 「ぼんたん飴」.",
"まんたん": "Bình chứa đầy tràn. Như 「ガソリン満タン」 (đổ đầy bình xăng).",
"わんたん": "Hoành thánh, món Trung Hoa gói nhân trong lớp vỏ mỏng.",
"ぜんたん": "Mép trước cùng.",
"くんたん": "Than làm từ vỏ trấu hun khói. Dùng để cải tạo đất.",
"でんたん": "Truyền đơn tuyên truyền rải từ trên không thời chiến.",
"えんたん": "Bột màu đỏ minium chì. Dùng trong sơn chống gỉ.",
"かんりょう": "Hoàn tất, kết thúc trọn vẹn. / Quan chức điều hành nền hành chính nhà nước.",
"ねんりょう": "Nhiên liệu: thứ đốt lên để lấy nhiệt hoặc động lực.",
"げんりょう": "Nguyên liệu làm ra sản phẩm. / Giảm lượng, giảm cân.",
"ぶんりょう": "Lượng của một thứ gì đó. Như 「分量を量る」 (đong đo phân lượng).",
"いんりょう": "Đồ uống. Như 「飲料水」 (nước uống).",
"おんりょう": "Độ lớn của âm thanh, âm lượng. / Oan hồn mang mối hận, bị cho là gieo tai hoạ.",
"ぜんりょう": "Tính tình tốt bụng và ngay thẳng.",
"せんりょう": "Quân đội chiếm đóng và cai quản vùng đất. / Cây 「千両」 quả đỏ dùng trang trí ngày Tết. / Vật liệu dùng để nhuộm vải.",
"しんりょう": "Khám và chữa bệnh. Như 「診療所」 (phòng khám).",
"てんりょう": "Vùng đất do Mạc phủ Edo trực tiếp cai quản.",
"まんりょう": "Cây bụi may mắn 「万両」, cho quả đỏ vào mùa đông.",
"きんりょう": "Cấm đánh bắt cá. Như 「禁漁期」 (mùa cấm đánh bắt).",
"がんりょう": "Bột màu không tan trong nước. Là nguyên liệu của sơn và màu vẽ.",
"ほんりょう": "Sở trường vốn có. Như 「本領発揮」 (phát huy sở trường).",
"ざんりょう": "Lượng còn lại.",
"うんりょう": "Lượng mây: tỉ lệ bầu trời bị mây che phủ.",
"さんりょう": "Núi và đồi. Cũng chỉ lăng mộ của Thiên hoàng.",
"はんりょう": "Một nửa lượng.",
"けんりょう": "Tiền công xem bói hoặc xem tướng.",
"へんりょう": "Đại lượng có thể thay đổi giá trị, biến số. Như 「確率変量」 (biến ngẫu nhiên).",
"かんばん": "Biển hiệu ghi tên cửa hàng hay hàng hoá. Như 「看板娘」 (cô gái mặt tiền của quán). / 「かんばん方式」, phương thức kanban trong hệ thống sản xuất Toyota.",
"けんばん": "Phím đàn piano và các nhạc cụ tương tự.",
"ほんばん": "Tình huống thật, buổi diễn thật, không phải tập dượt.",
"こんばん": "Tối nay. Như 「こんばんは」 (chào buổi tối).",
"なんばん": "Các xứ phương nam và người đến từ đó thời Muromachi, Edo. Cũng thấy trong tên món 「南蛮漬け」.",
"えんばん": "Vật hình tròn dẹt, cái đĩa. Như 「円盤投げ」 (ném đĩa).",
"せんばん": "Máy tiện, gia công bằng cách quay phôi. / Con số mười triệu. Như 「笑止千万」 (buồn cười hết sức).",
"さんばん": "Cái thứ ba. Như 「三番手」 (vị trí thứ ba).",
"ぎんばん": "Mặt băng của sân trượt băng.",
"げんばん": "Đĩa gốc dùng để sao chép. / Tấm phim gốc để in ảnh.",
"りんばん": "Luân phiên thay nhau theo thứ tự. Như 「輪番制」 (chế độ luân phiên).",
"いんばん": "Con dấu, hanko. Còn gọi là 「印形」 (ingyō).",
"おんばん": "Đĩa hát, đĩa than.",
"きんばん": "Thay phiên nhau đi trực, đi làm.",
"てんばん": "Mặt bàn, hoặc khay của lò nướng. Cũng đọc là tenpan.",
"がんばん": "Lớp đá cứng dưới lòng đất, nền đá. Như 「岩盤浴」 (tắm đá nóng).",
"もんばん": "Người gác cổng.",
"れんばん": "Số thứ tự liên tiếp. Như 「連番のチケット」 (vé đánh số liền nhau).",
"ひんばん": "Mã số sản phẩm.",
"○んばん\tばんばん": "Làm liên tục và mạnh mẽ. Như 「ばんばん働く」 (làm hết công suất).",
"しんばん": "Phán đoán và phân xử. / Trọng tài trong thi đấu.",
"よんばん": "Cái thứ tư. Trong bóng chày là cầu thủ đánh thứ tư.",
"やんばん": "Yangban, giai cấp thống trị của vương triều Triều Tiên.",
"まんが": "Tác phẩm kể chuyện bằng tranh và lời; manga.",
"れんが": "Gạch, vật liệu xây dựng nung từ đất sét. / 「連歌」, thơ liên cú do nhiều người nối nhau sáng tác.",
"げんが": "Bức tranh gốc dùng để sao chép. Tranh nguyên bản.",
