"せんが": "Tranh vẽ chỉ bằng đường nét.",
"ぶんが": "Nét phong nhã của người yêu thơ văn.",
"ぎんが": "Thiên hà, tập hợp vô số ngôi sao. Cũng chỉ dải Ngân Hà.",
"いんが": "Nguyên nhân và kết quả. / Quả báo từ kiếp trước. Như 「因果応報」 (nhân quả báo ứng).",
